P(tabla([{ t: 'Billetera de paso (completa)', k: 'a', code: true }, { t: 'Operaciones en su vida', k: 'txs', num: true }, { t: 'Reenvía sobre todo a', k: r => r.destinos[0] ? r.destinos[0].split(' ')[0] : '', code: true }], sumid));
P(caja('lim', 'Cautela sobre THORChain', '<p>Las direcciones de Ethereum reciben <b>17 M$</b> de stablecoins desde el 30-oct, pero solo <b>7,8 M$</b> vienen de TRON: mezclan dinero ajeno. Los 11,8 M$ de THORChain superan lo recibido del puente, así que <b>no puedo decir qué parte de esas operaciones es del robo</b>. Es otra forma de romper el rastro: el dinero sale, se cambia y entra por direcciones nuevas.</p>'));
